/**
 * WxCC Widget Fresh - Agent Widget
 * Handles customer emails and can request help from other agents
 * Now with multi-language support!
 */

import { Desktop } from "@wxcc-desktop/sdk";
import { sharedStyles } from "../shared/styles.js";

class WxccWidgetAgent extends HTMLElement {
    constructor() {
        super();
        this.attachShadow({ mode: 'open' });
        this.desktop = null;
        this.sdkReady = false;
        this.originalEmailBody = null; // to store the original email body as it is received from the flow
        this.currentLanguage = 'en';   // Default language
        this.translations = {};         // Store translations
    }

    async connectedCallback() {
        // Load translations first
        const lang = this.getLanguage();
        await this.loadTranslations(lang);
        
        console.log('[WxCC Widget Agent] Widget connected');
        
        this.render();
        this.initSDK();

        // Getting relevant data from the interaction
        try {
            const interaction = this.interactionData;
            console.log('[WxCC Widget Agent] interaction data: ', this.interactionData);

            const subject = interaction?.mediaProperties.emailSubject;
            const body = interaction?.callAssociatedData?.emailBody?.value;
            if (subject) {
                console.log('[WxCC Widget Agent] Email Subject:', subject);
                this.updateEmailSubject(subject);
            }
            if (body) {
                const text = body.trim();
                console.log('[WxCC Widget Agent] Email Body:', text);
                this.updateEmailBody(text);
            }
        }
        catch (error) {
            console.error('[WxCC Widget Agent] Error getting attributes:', error);
        }
    }

    /**
     * Get current language from Desktop SDK, attribute, or browser
     */
    getLanguage() {
        // Priority 1: Desktop SDK language
        try {
            if (Desktop?.config?.clientLocale) {
                const locale = Desktop.config.clientLocale;
                const lang = locale.split('-')[0]; // "en-US" -> "en"
                console.log('[WxCC Widget Agent] Language from Desktop SDK:', lang);
                return lang;
            }
        } catch (e) {
            // Desktop not ready yet
        }

        // Priority 2: Widget attribute
        const attrLang = this.getAttribute('language');
        if (attrLang) {
            console.log('[WxCC Widget Agent] Language from attribute:', attrLang);
            return attrLang;
        }

        // Priority 3: Browser language
        const browserLang = navigator.language.split('-')[0];
        console.log('[WxCC Widget Agent] Language from browser:', browserLang);
        return browserLang;
    }

    /**
     * Load translation file for specified language
     */
    async loadTranslations(lang) {
        try {
            // Try to load the specified language
            const response = await fetch(`./i18n/${lang}.json`);
            if (response.ok) {
                this.translations = await response.json();
                this.currentLanguage = lang;
                console.log(`[WxCC Widget Agent] ✅ Loaded translations for: ${lang}`);
                return;
            }
        } catch (error) {
            console.warn(`[WxCC Widget Agent] Could not load ${lang}.json:`, error);
        }

        // Fallback to English
        try {
            const fallback = await fetch('./i18n/en.json');
            this.translations = await fallback.json();
            this.currentLanguage = 'en';
            console.log('[WxCC Widget Agent] ⚠️ Falling back to English');
        } catch (error) {
            console.error('[WxCC Widget Agent] ❌ Failed to load any translations:', error);
            // Set minimal fallback
            this.translations = {
                labels: { subject: "Subject", body: "Body", notes: "Notes" },
                buttons: { getHelp: "Get Help" },
                defaults: { noSubject: "No subject", noBody: "No email body" }
            };
        }
    }

    /**
     * Translation helper - get translated string by path
     * @param {string} path - Path to translation key (e.g., "labels.subject")
     * @returns {string} Translated string
     */
    t(path) {
        const keys = path.split('.');
        let value = this.translations;
        
        for (const key of keys) {
            value = value?.[key];
            if (value === undefined) {
                console.warn(`[WxCC Widget Agent] Translation missing: ${path}`);
                return path; // Return key if translation not found
            }
        }
        
        return value;
    }

    initSDK() {
        console.log('[WxCC Widget Agent] Initializing SDK...');
        this.updateStatus('Initializing SDK...');

        try {
            // Initialize Desktop SDK (synchronous call, no await)
            Desktop.config.init();
            
            this.desktop = Desktop;
            this.sdkReady = true;
            
            console.log('[WxCC Widget Agent] ✅ SDK Ready!');

            // Make Desktop globally accessible with debug method
            window.Desktop = Desktop;
            Desktop.debugWidget = () => this.debugDesktop();
            
            console.log('[WxCC Widget Agent] 💡 Desktop accessible via: window.Desktop');
            console.log('[WxCC Widget Agent] 💡 Try: Desktop.debugWidget() on the console!');
            
            // Setup Get Help button
            this.setupGetHelpButton();
            
            this.updateStatus('SDK Ready');
            
        } catch (error) {
            console.error(`[WxCC Widget Agent] ${this.t('console.sdkError')}`, error);
            console.error('[WxCC Widget Agent] Error stack:', error.stack);
            this.updateStatus(`SDK Error: ${error.message}`);
        }
    }
    
    render() {
        this.shadowRoot.innerHTML = `
            <style>${sharedStyles}</style>

            <!-- some styling here to add margins to the widget -->
            <style>
                :host {
                    display: block;
                    padding: 0 16px;  /* 16px left & right */
                }
            </style>
            
            <!-- Email Display Section -->
            <div class="email-section">
                <div class="email-field">
                    <div class="email-label">${this.t('labels.subject')}</div>
                    <div class="email-value email-subject" id="emailSubject">
                        ${this.t('defaults.noSubject')}
                    </div>
                </div>
                
                <div class="email-field">
                    <div class="email-label">${this.t('labels.body')}</div>
                    <div class="email-body" id="emailBody">
                        ${this.t('defaults.noBody')}
                    </div>
                </div>
            </div>
            
            <!-- Notes Section -->
            <div class="notes-section">
                <div class="notes-label">${this.t('labels.notes')}</div>
                <textarea class="notes-input" id="notesInput" 
                    placeholder="${this.t('placeholders.addNotes')}"></textarea>
            </div>
            
            <!-- Button Section -->
            <div class="button-section">
                <button class="help-button" id="getHelpBtn">
                    ${this.t('buttons.getHelp')}
                </button>
                <div id="feedback" class="feedback"></div>
            </div>
        `;
    }
    
    updateStatus(message) {
        // Keep for error handling but don't show on UI anymore
        if (message.includes('Error')) {
            console.error('[WxCC Widget Agent]', message);
        }
    }
    
    updateEmailSubject(subject) {
        try {
            const el = this.shadowRoot?.getElementById('emailSubject');
            if (el) {
                el.textContent = subject || this.t('defaults.noSubject');
            } else {
                console.warn('[WxCC Widget Agent] emailSubject element not found in shadow DOM');
            }
        } catch (error) {
            console.error('[WxCC Widget Agent] ❌ Error in updateEmailSubject:', error);
        }
    }

    updateEmailBody(body) {
        try {
            // store original body
            this.originalEmailBody = body;
            
            const el = this.shadowRoot?.getElementById('emailBody');
            if (el) {
                const cleanBody = JSON.parse('"' + body + '"');
                el.innerHTML = cleanBody || this.t('defaults.noBody');
            } else {
                console.warn('[WxCC Widget Agent] emailBody element not found in shadow DOM');
            }
        } catch (error) {
            console.error('[WxCC Widget Agent] ❌ Error in updateEmailBody:', error);
        }
    }
    
    setupGetHelpButton() {
        try {
            const button = this.shadowRoot?.getElementById('getHelpBtn');
            if (button) {
                button.addEventListener('click', () => this.handleGetHelp());
                console.log('[WxCC Widget Agent] ✅ Get Help button listener attached');
            } else {
                console.warn('[WxCC Widget Agent] getHelpBtn element not found in shadow DOM');
            }
        } catch (error) {
            console.error('[WxCC Widget Agent] ❌ Error in setupGetHelpButton:', error);
        }
    }
    
    async handleGetHelp() {
        const button = this.shadowRoot?.getElementById('getHelpBtn');
        
        // Get current email data
        const subject = this.shadowRoot?.getElementById('emailSubject')?.textContent;
        const notes = this.shadowRoot?.getElementById('notesInput')?.value;
        const body = this.originalEmailBody;
        
        // Get customer info
        let customerName = null;
        let customerEmail = null;
        try {
            customerName = this.interactionData.customerName;
            customerEmail = this.interactionData.ani;
            console.log(`[WxCC Widget Agent] customer data: ${customerEmail} ${customerName}`);
        }
        catch (error){
            console.error('[WxCC Widget Agent] Error getting customer data from interaction:', error);
        }
      
        // Disable button during request
        if (button) button.disabled = true;
        
        try {
            console.log('[WxCC Widget Agent] 📤 Sending help request...');
            
            const response = await fetch('https://hooks.us.webexconnect.io/events/84PCLS8YJI', {
                method: 'POST',
                headers: {
                    'Content-Type': 'application/json',
                },
                body: JSON.stringify({
                    "customerName": customerName,
                    "customerEmail": customerEmail,
                    "inappmessaging.appId": "VI24093513",
                    "inappmessaging.userId": "6806ea7s-a04e-4fdb-9d86-0b33626f3577",
                    "emailSubject": subject,
                    "emailBody": body,
                    "notes": notes
                })
            });
            
            if (response.ok) {
                console.log('[WxCC Widget Agent] ✅ Help request sent successfully');
                console.log('Response:', await response.json());
                this.showFeedback('success', this.t('feedback.helpSent'));
            } else {
                console.error('[WxCC Widget Agent] ❌ Server error:', response.status);
                this.showFeedback('error', this.t('feedback.serverError'));
            }
            
        } catch (error) {
            console.error('[WxCC Widget Agent] ❌ Error sending help request:', error);
            this.showFeedback('error', this.t('feedback.requestFailed'));
        } finally {
            // Re-enable button
            if (button) button.disabled = false;
        }
    }
    
    showFeedback(type, message) {
        try {
            const feedback = this.shadowRoot?.getElementById('feedback');
            if (feedback) {
                feedback.className = `feedback ${type}`;
                feedback.textContent = message;
                feedback.style.display = 'block';
                
                // Hide after 3 seconds
                setTimeout(() => {
                    feedback.style.display = 'none';
                }, 3000);
            } else {
                console.warn('[WxCC Widget Agent] feedback element not found in shadow DOM');
            }
        } catch (error) {
            console.error('[WxCC Widget Agent] ❌ Error in showFeedback:', error);
        }
    }
    
    debugDesktop() {
        if (!this.desktop) {
            console.warn('[WxCC Widget Agent] Desktop SDK not initialized yet');
            return;
        }

        console.group('🖥️ Desktop SDK Debug Info');
        
        console.log('1️⃣ All Modules:', Object.keys(this.desktop));
        
        console.group('2️⃣ config');
        console.log('Properties:', Object.keys(this.desktop.config));
        console.log('Methods:', Object.keys(this.desktop.config).filter(k => typeof this.desktop.config[k] === 'function'));
        console.log('Client Locale:', this.desktop.config.clientLocale);
        console.groupEnd();
        
        console.group('3️⃣ agentStateInfo');
        console.log('Properties:', Object.keys(this.desktop.agentStateInfo));
        console.log('Methods:', Object.keys(this.desktop.agentStateInfo).filter(k => typeof this.desktop.agentStateInfo[k] === 'function'));
        console.log('Current State:', this.desktop.agentStateInfo.latestData);
        console.log('Idle Codes:', this.desktop.agentStateInfo.idleCodes);
        console.groupEnd();
        
        console.group('4️⃣ agentContact');
        console.log('Properties:', Object.keys(this.desktop.agentContact));
        console.log('Methods:', Object.keys(this.desktop.agentContact).filter(k => typeof this.desktop.agentContact[k] === 'function'));
        console.log('Task Map:', this.desktop.agentContact.taskMap);
        console.log('Selected Task:', this.desktop.agentContact.taskSelected);
        console.groupEnd();
        
        console.group('5️⃣ actions');
        console.log('Properties:', Object.keys(this.desktop.actions));
        console.log('Methods:', Object.keys(this.desktop.actions).filter(k => typeof this.desktop.actions[k] === 'function'));
        console.groupEnd();
        
        if (this.desktop.dialer) {
            console.group('6️⃣ dialer');
            console.log('Properties:', Object.keys(this.desktop.dialer));
            console.log('Methods:', Object.keys(this.desktop.dialer).filter(k => typeof this.desktop.dialer[k] === 'function'));
            console.groupEnd();
        }
        
        if (this.desktop.screenpop) {
            console.group('7️⃣ screenpop');
            console.log('Properties:', Object.keys(this.desktop.screenpop));
            console.log('Methods:', Object.keys(this.desktop.screenpop).filter(k => typeof this.desktop.screenpop[k] === 'function'));
            console.groupEnd();
        }
        
        if (this.desktop.logger) {
            console.group('8️⃣ logger');
            console.log('Properties:', Object.keys(this.desktop.logger));
            console.log('Methods:', Object.keys(this.desktop.logger).filter(k => typeof this.desktop.logger[k] === 'function'));
            console.groupEnd();
        }
        
        console.groupEnd();
        
        // Make Desktop globally accessible for easy testing
        window.Desktop = this.desktop;
        console.log('💡 Tip: Desktop is now available as window.Desktop');
        console.log('💡 Try: Desktop.agentStateInfo.latestData');
        console.log('💡 Try: Desktop.config.clientLocale');
    }
    
}

customElements.define('wxcc-widget-agent', WxccWidgetAgent);
console.log('[WxCC Widget Agent] Widget loaded');